import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independent archive and original-method inverse for the original NPC respawn ports. */
public final class StaticRespawnDelta {
 static final String P="local/lito381/server/",H=P+"NativeStaticNpcRespawn",R=P+"NativeStaticCancellationReplacement",C=P+"NativeCancellationNpcStatic",S=P+"NativeStaticNpcScene",M=P+"NativeStaticNpcMotion",PC=P+"ClientSession",CTX=P+"NativeAreaMaterialAction$Context",A=P+"NativeAreaMaterialAction",META=P+"NativeSkillTargetMetadata",DATA=P+"NativeStaticSpawnMetadata";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);return c;}
 static AbstractInsnNode prev(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static AbstractInsnNode next(AbstractInsnNode n){do{n=n.getNext();}while(n!=null&&n.getOpcode()<0);return n;}
 static byte[] body(ClassNode c,MethodNode m,String name){var t=new ClassNode();t.version=c.version;t.access=c.access;t.name=c.name;t.superName=c.superName;var copy=new MethodNode(m.access,name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(copy);t.methods.add(copy);var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);t.accept(w);return w.toByteArray();}
 static void dropLoads(MethodNode m,AbstractInsnNode call,int count){for(int k=0;k<count;k++)m.instructions.remove(prev(call));}
 static void guard(MethodNode m,MethodInsnNode call){dropLoads(m,call,2);var jump=next(call);var ret=next(jump);if(!(jump instanceof JumpInsnNode j)||j.getOpcode()!=IFNE||ret.getOpcode()!=RETURN)throw new AssertionError("retained bounded predicate");m.instructions.remove(jump);m.instructions.remove(ret);m.instructions.remove(call);}
 static void inverse(String cls,MethodNode m){for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call){
  if(cls.equals(META)&&call.owner.equals(DATA)&&call.name.equals("read")){dropLoads(m,call,1);m.instructions.remove(call);}
  else if(call.owner.equals(H)){
   if(cls.equals(R)&&call.name.equals("accepted")){dropLoads(m,call,1);m.instructions.remove(call);}
   else if(cls.equals(R)&&call.name.equals("dialogAllowed")||cls.equals(C)&&call.name.equals("castAllowed")||cls.equals(PC)&&call.name.equals("allowFrame"))guard(m,call);
   else if(cls.equals(R+"$Retired")&&call.name.equals("sendRetired")){dropLoads(m,call,1);call.owner=PC;call.name="nativeSelfOriginalSend";call.desc="([BLjava/lang/String;)V";call.setOpcode(INVOKEVIRTUAL);}
   else if(cls.equals(C)&&call.name.equals("publishNpc")){call.owner=C;call.name="publish";}
   else if(cls.equals(S)&&call.name.equals("prunable")){var key=prev(call);var hub=prev(key);if(!(key instanceof VarInsnNode k)||k.var!=1||!(hub instanceof VarInsnNode h)||h.var!=0)throw new AssertionError("canonical prune arguments");m.instructions.remove(hub);call.owner=R;call.desc="(ZL"+S+"$Key;)Z";}
   else throw new AssertionError("unreviewed port "+cls+"."+m.name+" -> "+call.name);
  }
 }}
 public static void main(String[]args)throws Exception{try(var base=new JarFile(args[0]);var jar=new JarFile(args[1])){var names=Set.of(R,R+"$Retired",C,S,S+"$Actor",M,PC,CTX,META,A);var changed=new HashSet<String>();var oldEntries=new HashSet<String>();for(var e:Collections.list(base.entries())){oldEntries.add(e.getName());var current=jar.getJarEntry(e.getName());if(current==null)throw new AssertionError("removed entry");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(current).readAllBytes()))changed.add(e.getName());}var fresh=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!oldEntries.contains(e.getName()))fresh.add(e.getName());if(!changed.equals(names.stream().map(n->n+".class").collect(java.util.stream.Collectors.toSet()))||!fresh.equals(Set.of(H+".class",H+"$Plan.class",H+"$Respawn.class",DATA+".class",DATA+"$Row.class")))throw new AssertionError("archive boundary");
 for(var name:names){var a=read(base,name);var b=read(jar,name);int addedFields=name.equals(CTX)||name.equals(S+"$Actor")?1:0,addedMethods=name.equals(R)||name.equals(C)||name.equals(M)||name.equals(A)?1:name.equals(S)?2:0;if(b.fields.size()!=a.fields.size()+addedFields||b.methods.size()!=a.methods.size()+addedMethods)throw new AssertionError("schema boundary "+name);for(int k=0;k<a.fields.size();k++){var f=a.fields.get(k);var g=b.fields.get(k);if(f.access!=g.access||!f.name.equals(g.name)||!f.desc.equals(g.desc)||!Objects.equals(f.value,g.value))throw new AssertionError("original field changed");}if(addedFields>0){var f=b.fields.get(b.fields.size()-1);if(!f.desc.equals("Ljava/lang/Object;")||!f.name.equals(name.equals(CTX)?"nativeStaticRespawnTarget":"nativeStaticRespawn")||f.access!=(name.equals(CTX)?0:ACC_VOLATILE))throw new AssertionError("bounded per-scene or cast continuation field");}
  for(var original:a.methods){String retained=original.name;if(name.equals(R)&&retained.equals("route"))retained="nativeStaticRespawnOriginalRoute";if(name.equals(M)&&retained.equals("dialog"))retained="nativeStaticRespawnOriginalDialog";if(name.equals(S)&&retained.equals("close"))retained="nativeStaticRespawnOriginalClose";if(name.equals(S)&&retained.equals("prune"))retained="nativeStaticRespawnOriginalPrune";if(name.equals(A)&&retained.equals("captureOutput"))retained="nativeStaticRespawnOriginalCaptureOutput";String select=retained;var m=b.methods.stream().filter(v->v.name.equals(select)&&v.desc.equals(original.desc)).findFirst().orElseThrow();inverse(name,m);if(!Arrays.equals(body(a,original,original.name),body(b,m,original.name)))throw new AssertionError("original method differs "+name+"."+original.name+original.desc);}
 }
 for(var name:List.of(H,H+"$Plan",H+"$Respawn")){var c=read(jar,name);for(var f:c.fields)if((f.access&ACC_STATIC)!=0&&(!f.desc.equals("Ljava/lang/String;")||f.value==null))throw new AssertionError("new static actor registry");for(var m:c.methods)for(var n:m.instructions)if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW&&(t.desc.contains("Executor")||t.desc.equals("java/lang/Thread"))||n instanceof MethodInsnNode call&&(call.owner.startsWith("java/sql/")||call.owner.startsWith("java/nio/file/")||call.owner.contains("GameStateStore")))throw new AssertionError("new worker/persistence path");}
 var data=read(jar,DATA);for(var f:data.fields)if((f.access&ACC_STATIC)!=0&&!(f.name.equals("rows")&&f.desc.equals("Ljava/util/Map;")&&(f.access&ACC_VOLATILE)!=0))throw new AssertionError("metadata schema");int queries=0;for(var m:data.methods)for(var n:m.instructions)if(n instanceof LdcInsnNode x&&x.cst instanceof String s&&s.startsWith("SELECT ")){if(!s.equals("SELECT npc_id FROM spawnlist_time")&&!s.equals("SELECT id,npc_templateid,count,locx,locy,randomx,randomy,heading,respawn_delay,mapid,movement_distance FROM spawnlist_npc"))throw new AssertionError("unreviewed SQL");queries++;}if(queries!=2)throw new AssertionError("two readonly static queries only");
 }System.out.println("PASS independent inverse: original methods/archive retained; bounded scene/cast fields, final synchronized frame predicate and two readonly bootstrap queries only");}
}
